/// <summary>
/// Extension of method endUpdate
/// </summary>
public void endUpdate()
{
    next endUpdate();

    AgreementLine avaAgreementLine = AgreementLine::find(purchLine.MatchingAgreementLine);

    avaAgreementLine.avaUpdateSubRestQty();
    //avaAgreementLine.avaUpdateMainRestQty();
}

/// <summary>
/// Extension of method setPurchLine
/// </summary>
public void setPurchLine()
{
    next setPurchLine();

    purchLine.PurchQty      = tmpPurchLine.PurchQty;
    purchLine.PurchUnit     = tmpPurchLine.Units;
    purchLine.LineAmount    = purchLine.calcLineAmount(tmpPurchLine.PurchQty);
}
